      left: 0;
      top: 0;
      width: 100%;
      box-sizing: border-box;
      padding: calc(env(safe-area-inset-top) + 10px) 14px 10px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      pointer-events: none;
      color: #18314f;
      text-shadow: 0 2px 0 rgba(255,255,255,0.35);
      font-weight: 800;
    }
    .pill {
      background: rgba(255,255,255,0.78);
      border: 2px solid rgba(24,49,79,0.14);
      border-radius: 999px;
      padding: 8px 12px;
      box-shadow: 0 8px 20px rgba(24,49,79,0.08);
      font-size: 14px;
    }
    .center {
      position: fixed;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      pointer-events: none;
      padding: 24px;
      box-sizing: border-box;
    }
    .panel {
      width: min(88vw, 420px);
      background: rgba(255,255,255,0.9);
      border-radius: 24px;
      box-shadow: 0 16px 40px rgba(24,49,79,0.18);
      border: 2px solid rgba(24,49,79,0.08);
      padding: 22px 18px;
      text-align: center;
      color: #18314f;
      pointer-events: auto;
    }
    .title {
      font-size: 30px;
      font-weight: 900;
      margin: 0 0 8px;
    }
    .desc {
      font-size: 15px;
      line-height: 1.6;
      opacity: 0.9;
      margin: 0 0 16px;
    }
    .btn {
      appearance: none;
      border: 0;
      background: linear-gradient(180deg, #ffb347 0%, #ff8a3d 100%);
      color: white;
      font-size: 18px;
      font-weight: 900;
      padding: 14px 24px;
      border-radius: 999px;
      box-shadow: 0 10px 20px rgba(255,138,61,0.3);
      min-width: 160px;
    }
    .tip {
      margin-top: 12px;
      font-size: 13px;
      opacity: 0.75;
    }
    #toast {
      position: fixed;
      left: 50%;
      bottom: calc(env(safe-area-inset-bottom) + 20px);
      transform: translateX(-50%);
      background: rgba(24,49,79,0.88);
      color: #fff;
      padding: 8px 14px;
      border-radius: 999px;
      font-size: 14px;
      font-weight: 800;
      opacity: 0;
      transition: opacity .2s ease;
      pointer-events: none;
    }
  </style>
